package bits.ui;
import bits.dao.UserDAO; import javax.swing.*; import java.awt.*; import java.sql.SQLException;
public class RegisterFrame extends JDialog {
 private final JTextField name=new JTextField(20),email=new JTextField(20);private final JPasswordField password=new JPasswordField(20),confirm=new JPasswordField(20);
 public RegisterFrame(JFrame owner){super(owner,"Create BITS account",true);setSize(480,370);setLocationRelativeTo(owner);JPanel p=new JPanel(new GridLayout(0,2,10,12));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));p.add(new JLabel("Name"));p.add(name);p.add(new JLabel("Email"));p.add(email);p.add(new JLabel("Password"));p.add(password);p.add(new JLabel("Confirm password"));p.add(confirm);JButton create=new JButton("Register");p.add(new JLabel());p.add(create);p.setBorder(BorderFactory.createEmptyBorder(22,22,22,22));add(p);Theme.styleWindow(this);create.setBackground(Theme.ACCENT);create.setForeground(java.awt.Color.WHITE);create.addActionListener(e->register());}
 private void register(){String n=name.getText().trim(),em=email.getText().trim(),pw=new String(password.getPassword());if(n.isEmpty()||em.isEmpty()||pw.length()<6){JOptionPane.showMessageDialog(this,"Enter name, email, and a password of at least 6 characters.");return;}if(!pw.equals(new String(confirm.getPassword()))){JOptionPane.showMessageDialog(this,"Passwords do not match.");return;}try{if(new UserDAO().register(n,em,pw)){JOptionPane.showMessageDialog(this,"Account created. You can now sign in.");dispose();}else JOptionPane.showMessageDialog(this,"That email is already registered.");}catch(SQLException ex){LoginFrame.dbError(ex);}}
}
